(1, 'Equipamento MCR E', '<p>As diferentes c&eacute;lulas de encaixotamento usam as especifica&ccedil;&otilde;es abaixo:</p>\r\n<p>&nbsp;</p>\r\n<ul>\r\n<li>MCR ED - C&eacute;lula rob&oacute;tica de encaixotamento que usa rob&ocirc;s do tipo&nbsp;<em><strong>DELTA</strong></em>.</li>\r\n<li>MCR ES - C&eacute;lula rob&oacute;tica de encaixotamento que usa rob&ocirc;s do tipo <em><strong>SCARA</strong></em>.</li>\r\n<li>MCR EA - C&eacute;lula rob&oacute;tica de encaixotamento que usa rob&ocirc;s do tipo&nbsp;<em><strong>ANTROPOM&Oacute;RFICO.</strong></em></li>\r\n</ul>', NULL, 1, 1, '2025-04-01 10:06:24', '2025-12-29 17:14:23', NULL),
