(39, 'Tipo de CIP', '<ol>\r\n<li>Autom&aacute;tico - as caracter&iacute;sticas do sistema autom&aacute;tico s&atilde;o:\r\n<ol>\r\n<li>Sem necessidade de montagem da falsa garrafa, tem o acionamento AUTOM&Aacute;TICO.</li>\r\n<li>V&aacute;lvulas de processo com acionamento AUTOM&Aacute;TICO.</li>\r\n<li>Tempos de processo controlados AUTOMATICAMENTE por receita.</li>\r\n<li>Se houver equipamento trabalhando trocando sinais e em autom&aacute;tico junto com a enchedora, a troca de processos &eacute; autom&aacute;tica, por receita.</li>\r\n</ol>\r\n</li>\r\n<li>Semi-Autom&aacute;tico - as caracter&iacute;sticas do sistema s&atilde;o:\r\n<ol>\r\n<li>Falsa garrafa com montagem MANUAL.</li>\r\n<li>V&aacute;lvulas de processo com acionamento AUTOM&Aacute;TICO.</li>\r\n<li>Tempos de processo controlados AUTOMATICAMENTE por receita.</li>\r\n<li>Se houver equipamento trabalhando trocando sinais e em autom&aacute;tico junto com a enchedora, a troca de processos &eacute; autom&aacute;tica, por receita.</li>\r\n</ol>\r\n</li>\r\n<li>Manual - as caracter&iacute;sticas do sistema s&atilde;o:\r\n<ol>\r\n<li>Falsa garrafa com montagem MANUAL.</li>\r\n<li>V&aacute;lvulas de processo com acionamento MANUAL.</li>\r\n<li>Tempos de processo controlados MANUALMENTE pelo operador.</li>\r\n<li>Equipamento N&Atilde;O &eacute; preparado para troca de sinais.</li>\r\n</ol>\r\n</li>\r\n</ol>\r\n<ol>\r\n<li style=\"list-style-type: none;\">&nbsp;</li>\r\n</ol>', NULL, 39, 1, '2025-04-15 14:08:46', '2025-05-28 16:01:52', NULL),
