(61, 'Pé direito no local de instalação', NULL, 'mm', 61, 1, '2025-04-15 14:44:26', '2025-05-02 08:35:33', '2025-05-02 08:35:33'),
(62, 'Dispositivo porta-KIT', NULL, NULL, 62, 1, '2025-04-15 14:46:22', '2025-05-28 16:08:35', NULL),
(63, 'Bandeja de esgotamento de válvula', '<ol>\r\n<li>Acess&oacute;rio usado principalmente em enchedoras eletr&ocirc;nicas instaladas em linhas maiores ou mais complexas.</li>\r\n<li>Se destina a fazer o escoamento dos residuais de &aacute;gua contidos nas tubula&ccedil;&otilde;es e taque de produto da enchedora.</li>\r\n<li>Como funciona:\r\n<ol>\r\n<li>Quando inicia o bombeamento do produto na sala de prepara&ccedil;&atilde;o, todo o residual de &aacute;gua da tubula&ccedil;&atilde;o e empurrado para o tanque da enchedora.</li>\r\n<li>Esse residual dilui a primeira batelada de produto que chega no tanque da enchedora, quando esse produto precisa ser descartado se faz o uso da bandeja.</li>\r\n<li>Com o uso da bandeja &eacute; eliminada a sujeira na base do equipamento ou o descarte de frasco e tampas.</li>\r\n</ol>\r\n</li>\r\n</ol>', NULL, 63, 1, '2025-04-15 14:47:20', '2025-05-28 16:09:05', NULL),
(64, 'Sensor de metais na saída do equipamento', '<ol>\r\n<li>Item opcional usado na garantia da qualidade.</li>\r\n<li>Destinado para detectar corpos met&aacute;licos nos frascos.</li>\r\n<li>Existem duas vers&otilde;es do sistema:\r\n<ol>\r\n<li>Sozinho, funcionando como simples alarme - alarme informa a suspeita e para a enchedora, o operador procura a frente do sensor o frasco desconforme.</li>\r\n<li>Em conjunto com o rejeito autom&aacute;tico - com essa op&ccedil;&atilde;o o sistema pode:\r\n<ol>\r\n<li>Descartar o frasco suspeito.</li>\r\n<li>Informar a esta&ccedil;&atilde;o da enchedora e tapador que pode ter originado a n&atilde;o conformidade.</li>\r\n</ol>\r\n</li>\r\n</ol>\r\n</li>\r\n</ol>', NULL, 64, 1, '2025-04-15 14:48:06', '2025-05-28 16:09:21', NULL),
(65, 'Sensor de falta de tampas na saída do equipamento', '<ol>\r\n<li>Item opcional usado na garantia da qualidade.</li>\r\n<li>Destinado para detectar falta de tampas e at&eacute; um certo grau de n&atilde;o conformidade de aplica&ccedil;&atilde;o da tampa.</li>\r\n<li>Existem duas vers&otilde;es do sistema:\r\n<ol>\r\n<li>Sozinho, funcionando como simples alarme - alarme informa a suspeita e para a enchedora, o operador procura a frente do sensor o frasco desconforme.</li>\r\n<li>Em conjunto com o rejeito autom&aacute;tico - com essa op&ccedil;&atilde;o o sistema pode:\r\n<ol>\r\n<li>Descartar o frasco suspeito.</li>\r\n<li>Informar a esta&ccedil;&atilde;o do tapador que pode ter originado a n&atilde;o conformidade.</li>\r\n</ol>\r\n</li>\r\n</ol>\r\n</li>\r\n</ol>', NULL, 65, 1, '2025-04-15 14:48:28', '2025-05-02 09:01:07', NULL),
(66, 'Rejeito de frascos na saída do equipamento', '<ol>\r\n<li>Item opcional usado na garantia da qualidade.</li>\r\n<li>Destinado para descarte de frascos na sa&iacute;da de equipamentos como:\r\n<ol>\r\n<li>Enchedoras.</li>\r\n<li>Tapadores.</li>\r\n<li>Rotuladoras.</li>\r\n</ol>\r\n</li>\r\n<li>O equipamento sempre ser&aacute; usado em conjunto com algum controle de qualidade especificado previamente.</li>\r\n</ol>', NULL, 66, 1, '2025-04-15 14:48:46', '2025-10-21 11:23:34', NULL),
(67, 'Enclausuramento com pressão positiva', '<ol>\r\n<li>Item opcional usado em enchedoras e tapadores.</li>\r\n<li>Usado essencialmente em envases com necessidade de controle microbiol&oacute;gico.</li>\r\n<li>Destina-se a manter uma atmosfera controlada nas &aacute;reas onde frascos com produto estiverem abertos.</li>\r\n<li>Sempre ser&aacute; usado em equipamentos com enclausuramento integral (com teto).</li>\r\n<li>Composto por:\r\n<ol>\r\n<li>Enclausuramento com teto.</li>\r\n<li>Bombas para insuflar o ar no equipamento.</li>\r\n<li>Filtros para o ar a ser insuflado.</li>\r\n</ol>\r\n</li>\r\n</ol>', NULL, 67, 1, '2025-04-15 14:49:00', '2025-05-28 16:16:02', NULL),
(68, 'Controle de contra-pressão (ISOBAROMÉTRICO)', NULL, NULL, 68, 1, '2025-04-15 14:49:53', '2025-05-28 16:15:44', NULL),
(69, 'Sistema de COP para base de frascos da enchedora', '<ol>\r\n<li>Item opcional usado em enchedoras BASE que usam frascos de vidro.</li>\r\n<li>Funcionamento:\r\n<ol>\r\n<li>Sistema detecta a quebra do frasco na enchedora.</li>\r\n<li>Sistema impede a entrada de novo frasco na esta&ccedil;&atilde;o da ocorr&ecirc;ncia (configur&aacute;vel).</li>\r\n<li>Sistema aciona uma s&eacute;rie de jatos de &aacute;gua que removem os res&iacute;duos de vidro.</li>\r\n<li>Sistema DEVE ser usado em conjunto com rejeito autom&aacute;tico (configur&aacute;vel).</li>\r\n<li>Sistema libera esta&ccedil;&atilde;o para funcionamento normal (configur&aacute;vel).</li>\r\n</ol>\r\n</li>\r\n</ol>', NULL, 69, 1, '2025-04-15 14:50:37', '2025-05-28 16:15:25', NULL),
(70, 'Sistema de COP para tapadores', '<ol>\r\n<li>Item opcional usado em tapadores BASE que usam frascos de vidro.</li>\r\n<li>Funcionamento:\r\n<ol>\r\n<li>Sistema detecta a quebra do frasco no tapador.</li>\r\n<li>Sistema impede a entrada de novo frasco na esta&ccedil;&atilde;o da ocorr&ecirc;ncia (configur&aacute;vel).</li>\r\n<li>Sistema aciona uma s&eacute;rie de jatos de &aacute;gua que removem os res&iacute;duos de vidro.</li>\r\n<li>Sistema DEVE ser usado em conjunto com rejeito autom&aacute;tico (configur&aacute;vel).</li>\r\n<li>Sistema libera esta&ccedil;&atilde;o para funcionamento normal (configur&aacute;vel).</li>\r\n</ol>\r\n</li>\r\n</ol>', NULL, 70, 1, '2025-04-15 14:50:53', '2025-05-28 16:15:03', NULL),
