(158, 'Tipo de CIP', '<ol>\r\n<li>Autom&aacute;tico - las caracter&iacute;sticas del sistema autom&aacute;tico son:\r\n<ol>\r\n<li>Sin necesidad de montar la falsa botella, tiene el accionamiento AUTOM&Aacute;TICO.</li>\r\n<li>V&aacute;lvulas de proceso con accionamiento AUTOM&Aacute;TICO.</li>\r\n<li>Tiempos de proceso controlados AUTOM&Aacute;TICAMENTE por receta.</li>\r\n<li>Si hay equipo trabajando intercambiando se&ntilde;ales y en autom&aacute;tico junto con la llenadora, el cambio de procesos es autom&aacute;tico, por receta.</li>\r\n</ol>\r\n</li>\r\n<li>Semiautom&aacute;tico - las caracter&iacute;sticas del sistema son:<br>\r\n<ol>\r\n<li>Falsa botella con montaje MANUAL.</li>\r\n<li>V&aacute;lvulas de proceso con accionamiento AUTOM&Aacute;TICO.</li>\r\n<li>Tiempos de proceso controlados AUTOM&Aacute;TICAMENTE por receta.</li>\r\n<li>Si hay equipo trabajando intercambiando se&ntilde;ales y en autom&aacute;tico junto con la llenadora, el cambio de procesos es autom&aacute;tico, por receta.</li>\r\n</ol>\r\n</li>\r\n<li>Manual - las caracter&iacute;sticas del sistema son:<br>\r\n<ol>\r\n<li>Falsa botella con montaje MANUAL.</li>\r\n<li>V&aacute;lvulas de proceso con accionamiento MANUAL.</li>\r\n<li>Tiempos de proceso controlados MANUALMENTE por el operador.</li>\r\n<li>El equipo NO est&aacute; preparado para intercambio de se&ntilde;ales.</li>\r\n</ol>\r\n</li>\r\n</ol>\r\n<ol>\r\n<li style=\"list-style-type: none;\">&nbsp;</li>\r\n</ol>', NULL, 39, 2, '2025-10-20 13:35:16', '2025-10-20 13:35:16', NULL),
