(179, 'Dispositivo portador de KIT', NULL, NULL, 62, 2, '2025-10-21 09:52:06', '2025-10-21 09:52:06', NULL),
(180, 'Bandeja de desagüe de válvula', '<ol>\r\n<li>Accesorio utilizado principalmente en llenadoras electr&oacute;nicas instaladas en l&iacute;neas mayores o m&aacute;s complejas.</li>\r\n<li>Se destina a realizar el drenaje de los residuos de agua contenidos en las tuber&iacute;as y tanque de producto de la llenadora.</li>\r\n<li>Funcionamiento:<br>\r\n<ol>\r\n<li>Al iniciar el bombeo del producto en la sala de preparaci&oacute;n, todo el residual de agua de la tuber&iacute;a es empujado hacia el tanque de la llenadora.</li>\r\n<li>Este residual diluye el primer lote de producto que llega al tanque de la llenadora. Cuando este producto necesita ser descartado, se utiliza la bandeja.</li>\r\n<li>Con el uso de la bandeja se elimina la suciedad en la base del equipo o el descarte de frascos y tapas.</li>\r\n</ol>\r\n</li>\r\n</ol>', NULL, 63, 2, '2025-10-21 11:11:20', '2025-10-21 11:12:37', NULL),
(181, 'Detector de metales en la salida del equipo', '<ol>\r\n<li>Art&iacute;culo opcional utilizado en la garant&iacute;a de calidad.</li>\r\n<li>Destinado a detectar cuerpos met&aacute;licos en los frascos.</li>\r\n<li>Existen dos versiones del sistema:<br>\r\n<ol>\r\n<li>Individual, funcionando como alarma simple: la alarma indica la sospecha y detiene la llenadora; el operador busca el frasco no conforme frente al sensor.</li>\r\n<li>En conjunto con el rechazo autom&aacute;tico: con esta opci&oacute;n el sistema puede:<br>\r\n<ol>\r\n<li>Descartar el frasco sospechoso.</li>\r\n<li>Informar a la estaci&oacute;n de la llenadora y el tapador sobre el posible origen de la no conformidad.</li>\r\n</ol>\r\n</li>\r\n</ol>\r\n</li>\r\n</ol>', NULL, 64, 2, '2025-10-21 11:13:58', '2025-10-21 11:15:32', NULL),
(182, 'Detector de falta de tapas en la salida del equipo', '<ol>\r\n<li>Art&iacute;culo opcional utilizado en la garant&iacute;a de calidad.</li>\r\n<li>Destinado a detectar cuerpos met&aacute;licos en los frascos.</li>\r\n<li>Existen dos versiones del sistema:<br>\r\n<ol>\r\n<li>Individual, funcionando como alarma simple: la alarma indica la sospecha y detiene la llenadora; el operador busca el frasco no conforme frente al sensor.</li>\r\n<li>En conjunto con el rechazo autom&aacute;tico: con esta opci&oacute;n el sistema puede:<br>\r\n<ol>\r\n<li>Descartar el frasco sospechoso.</li>\r\n<li>Informar a la estaci&oacute;n de la llenadora y el tapador sobre el posible origen de la no conformidad.</li>\r\n</ol>\r\n</li>\r\n</ol>\r\n</li>\r\n</ol>', NULL, 65, 2, '2025-10-21 11:17:45', '2025-10-21 11:18:30', NULL),
(183, 'Rechazo de frascos en la salida del equipo', '<ol>\r\n<li>Art&iacute;culo opcional utilizado en la garant&iacute;a de calidad.</li>\r\n<li>Destinado al descarte de frascos en la salida de equipos como:\r\n<ol>\r\n<li>Llenadoras.</li>\r\n<li>Tapadoras.</li>\r\n<li>Etiquetadoras.</li>\r\n</ol>\r\n</li>\r\n<li>El equipo siempre ser&aacute; utilizado en conjunto con alg&uacute;n control de calidad especificado previamente.</li>\r\n</ol>', NULL, 66, 2, '2025-10-21 11:21:55', '2025-10-21 11:23:25', NULL),
(184, 'Enclaustramiento con presión positiva', '<ol>\r\n<li>Art&iacute;culo opcional utilizado en llenadoras y tapadoras.</li>\r\n<li>Usado esencialmente en envases con necesidad de control microbiol&oacute;gico.</li>\r\n<li>Se destina a mantener una atm&oacute;sfera controlada en las &aacute;reas donde los frascos con producto est&eacute;n abiertos.</li>\r\n<li>Siempre ser&aacute; utilizado en equipos con enclaustramiento integral (con techo).</li>\r\n<li>Compuesto por:<br>\r\n<ol>\r\n<li>Enclaustramiento con techo.</li>\r\n<li>Bombas para insuflar aire en el equipo.</li>\r\n<li>Filtros para el aire a ser insuflado.</li>\r\n</ol>\r\n</li>\r\n</ol>', NULL, 67, 2, '2025-10-21 11:25:10', '2025-10-21 11:26:32', NULL),
(185, 'Control de contrapresión (ISOBAROMÉTRICO)', NULL, NULL, 68, 2, '2025-10-21 11:34:07', '2025-10-21 11:34:07', NULL),
(186, 'Sistema de COP para base de frascos de la llenadora', '<ol>\r\n<li>Art&iacute;culo opcional utilizado en llenadoras BASE que usan frascos de vidrio.</li>\r\n<li>Funcionamiento:<br>\r\n<ol>\r\n<li>El sistema detecta la rotura del frasco en la llenadora.</li>\r\n<li>Impide la entrada de un nuevo frasco en la estaci&oacute;n de la ocurrencia (configurable).</li>\r\n<li>Act&uacute;a una serie de chorros de agua que eliminan los residuos de vidrio.</li>\r\n<li>DEBE utilizarse junto con el rechazo autom&aacute;tico (configurable).</li>\r\n<li>Libera la estaci&oacute;n para funcionamiento normal (configurable).</li>\r\n</ol>\r\n</li>\r\n</ol>', NULL, 69, 2, '2025-10-21 11:37:21', '2025-10-21 11:38:46', NULL),
(187, 'Sistema de COP para tapadoras', '<ol>\r\n<li>Art&iacute;culo opcional utilizado en tapadoras BASE que usan frascos de vidro.</li>\r\n<li>Funcionamiento:\r\n<ol>\r\n<li>El sistema detecta la rotura del frasco en la tapadora.</li>\r\n<li>Impide la entrada de un nuevo frasco en la estaci&oacute;n de la ocurrencia (configurable).</li>\r\n<li>Activa una serie de chorros de agua que eliminan los residuos de vidro.</li>\r\n<li>DEBE utilizarse junto con el rechazo autom&aacute;tico (configurable).</li>\r\n<li>Libera la estaci&oacute;n para funcionamiento normal (configurable).</li>\r\n</ol>\r\n</li>\r\n</ol>', NULL, 70, 2, '2025-10-21 13:27:45', '2025-10-21 13:28:57', NULL),
