(221, 'Marca del alimentador', NULL, NULL, 109, 2, '2025-10-22 08:46:58', '2025-10-22 08:46:58', NULL),
(222, 'Detección de fin de etiqueta en la bobina', NULL, NULL, 110, 2, '2025-10-22 08:48:24', '2025-10-22 08:48:24', NULL),
(223, 'Alineador de etiquetas', '<ol>\r\n<li>Opcional utilizado para mejora de la calidad de aplicaci&oacute;n.</li>\r\n<li>Tambi&eacute;n indicado para m&aacute;quinas de alta velocidad.</li>\r\n</ol>', NULL, 111, 2, '2025-10-22 08:49:32', '2025-10-22 08:50:08', NULL),
(224, 'Segundo soporte de bobina', '<ol>\r\n<li>Reduce el tiempo de parada para cambio de etiqueta.</li>\r\n</ol>', NULL, 112, 2, '2025-10-22 08:52:06', '2025-10-22 08:52:06', NULL),
(225, 'Control de ausencia de etiqueta', '<ol>\r\n<li>Art&iacute;culo opcional utilizado para garantizar la calidad.</li>\r\n<li>Destinado a detectar falta de etiquetas en los frascos.</li>\r\n<li>Existen dos versiones del sistema:<br>\r\n<ol>\r\n<li>Individual, funcionando como alarma simple - la alarma informa la sospecha y detiene la etiquetadora, el operador busca el frasco no conforme frente al sensor.</li>\r\n<li>En conjunto con el rechazo autom&aacute;tico - con esta opci&oacute;n el sistema puede:\r\n<ol>\r\n<li>Descartar el frasco sospechoso.</li>\r\n</ol>\r\n</li>\r\n</ol>\r\n</li>\r\n</ol>', NULL, 113, 2, '2025-10-22 08:54:42', '2025-10-22 08:55:36', NULL),
(226, 'Equipo MEP', NULL, NULL, 114, 2, '2025-10-22 08:57:33', '2025-10-22 08:57:33', NULL),
(227, 'Material del equipo (pint.)', NULL, NULL, 115, 2, '2025-10-22 08:59:08', '2025-10-22 08:59:08', NULL),
(228, 'Regulación de altura del enroscador', NULL, NULL, 126, 2, '2025-10-22 09:01:06', '2025-10-22 09:01:06', NULL),
(229, 'Equipo (GENERACIÓN CLASSIC)', NULL, NULL, 127, 2, '2025-10-22 09:04:57', '2025-10-22 09:04:57', NULL),
(230, 'Muestras de cajas especificadas en el anexo', NULL, NULL, 128, 2, '2025-10-22 09:07:55', '2025-10-22 09:07:55', NULL),
(231, 'Equipamento MTF', NULL, NULL, 129, 1, '2025-12-18 06:51:14', '2025-12-18 06:51:14', NULL),
(232, 'Lado de entrada de frascos na rotuladora', '<p>A avalia&ccedil;&atilde;o do sentido se faz posicionando o observador &agrave; frente da m&aacute;quina, (lado oposto ao quadro el&eacute;trico).</p>', NULL, 130, 1, '2025-12-19 11:23:56', '2025-12-19 11:29:35', NULL),
(233, 'Equipamento MCC', NULL, NULL, 131, 1, '2025-12-19 14:07:56', '2025-12-19 14:07:56', NULL),
(234, 'Possui trocador de calor', NULL, NULL, 132, 1, '2025-12-19 14:10:07', '2025-12-19 14:10:07', NULL),
(235, 'Necessita passagem direta de produto', '<p>A passagem especial consiste em sistema que permite alimentar a enchedora posterior ao carbonatador sem que o flu&iacute;do passe pelo carboatador. Esse processo &eacute; poss&iacute;vel mas precisa de orienta&ccedil;&atilde;o ao cliente para que ele prepare a aplimenta&ccedil;&atilde;o do tanque isobarom&eacute;trico de maneira tecnicamente correta.</p>', NULL, 133, 1, '2025-12-19 14:14:12', '2025-12-19 14:14:12', NULL),
(236, 'Tipo de CIP', '<ol>\r\n<li>Manual - as caracter&iacute;sticas do sistema s&atilde;o:<br>\r\n<ol>\r\n<li>V&aacute;lvulas de processo com acionamento MANUAL.</li>\r\n<li>Tempos de processo controlados MANUALMENTE pelo operador.</li>\r\n</ol>\r\n</li>\r\n</ol>', NULL, 134, 1, '2025-12-19 14:19:23', '2025-12-19 14:19:23', NULL),
(237, 'Marca de bombas', NULL, NULL, 135, 1, '2025-12-19 14:25:13', '2025-12-19 14:25:13', NULL),
(238, 'Volume de CO2', NULL, 'gCO2/l', 136, 1, '2025-12-19 14:41:38', '2025-12-19 14:41:38', NULL),
(239, 'Temperatura de gaseificação', NULL, '°c', 137, 1, '2025-12-19 14:45:24', '2025-12-19 14:45:24', NULL),
(240, 'Equipamento MTA', NULL, NULL, 138, 1, '2025-12-20 07:50:38', '2025-12-20 07:50:38', NULL),
(241, 'Filtro do ventilador', NULL, NULL, 139, 1, '2025-12-20 07:51:43', '2025-12-20 07:51:43', NULL),
(242, 'Regulagem das varandas', NULL, NULL, 140, 1, '2025-12-20 07:54:04', '2025-12-20 07:54:04', NULL),
(243, 'Material do equipamento (i)', NULL, NULL, 141, 1, '2025-12-20 07:57:08', '2025-12-20 07:57:08', NULL),
(244, '\"Y\" de transferência', NULL, NULL, 142, 1, '2025-12-20 08:00:53', '2025-12-20 08:00:53', NULL),
(245, 'Marca do ventilador', NULL, NULL, 143, 1, '2025-12-20 08:02:01', '2025-12-20 08:02:01', NULL),
(246, 'Material do guia de gargalo', NULL, NULL, 144, 1, '2025-12-20 08:04:56', '2025-12-20 08:04:56', NULL),
(247, 'Automação de linha', '<p><strong>Sem automa&ccedil;&atilde;o</strong> - os ventiladores permanecem ligados &agrave; rota&ccedil;&atilde;o nominal durante toda opera&ccedil;&atilde;o.</p>\r\n<p><strong>Automa&ccedil;&atilde;o b&aacute;sica </strong>- trechos do transportador s&atilde;o monitorados por sensores e quando esses trechos entram em ac&uacute;mulo os ventiladores s&atilde;o desligados (recomendado para linhas m&eacute;dias e grandes).</p>\r\n<p><strong>Automa&ccedil;&atilde;o</strong> - trechos do transportador s&atilde;o monitorados por sensores e quando esses trechos entram em ac&uacute;mulo os ventiladores s&atilde;o modulados atrav&eacute;s de inversores de frequ&ecirc;ncia (recomendado para linhas m&eacute;dias e grandes).</p>\r\n<p>&nbsp;</p>', NULL, 145, 1, '2025-12-20 08:12:11', '2025-12-20 08:12:11', NULL),
(248, 'Equipamento transportador de frascos', NULL, NULL, 146, 1, '2025-12-20 09:37:41', '2025-12-20 09:37:41', NULL),
(249, 'Bandeja coletora antes da enchedora', NULL, NULL, 147, 1, '2025-12-20 09:40:15', '2025-12-20 09:40:15', NULL),
(250, 'Bandeja coletora DEPOIS da enchedora', '<p>Define o uso de bandeja coletora de l&iacute;quidos sob as esteiras nos trechos da linha que se encontram ap&oacute;s a enchedora.</p>', NULL, 148, 1, '2025-12-20 09:41:55', '2025-12-20 09:41:55', NULL),
(251, 'Cobertura superior', '<p>Consiste no uso de cobertura met&aacute;lica nos trechos de transporte em que o frasco estar&aacute; sendo transportado sem a tampa (normalmente antes da enchedora).</p>', NULL, 149, 1, '2025-12-20 09:44:59', '2025-12-20 09:44:59', NULL),
(252, 'Posição de montagem dos motoredutores', NULL, NULL, 150, 1, '2025-12-20 09:49:48', '2025-12-20 09:49:48', NULL),
(253, 'Capa de proteção nos acionamentos', '<p>Capa de prote&ccedil;&atilde;o met&aacute;lica oferecida de forma opcional, com custo adicional ao projeto.</p>', NULL, 151, 1, '2025-12-20 09:51:29', '2025-12-20 09:51:29', NULL),
(254, 'Modelo do motoredutor', NULL, NULL, 152, 1, '2025-12-20 09:57:02', '2025-12-20 09:57:02', NULL),
(255, 'Varanda com posicionador de setup', '<p>Opcional facilita e padroniza a regulagem das varandas em eventuais setups.</p>', NULL, 153, 1, '2025-12-20 10:31:32', '2025-12-20 10:31:32', NULL),
(256, 'Tipo do elemento de transporte', NULL, NULL, 154, 1, '2025-12-20 10:35:51', '2025-12-20 10:35:51', NULL),
