(258, 'Fornecimento do elemento de transporte', NULL, NULL, 156, 1, '2025-12-20 10:42:06', '2025-12-20 10:42:06', NULL),
(259, 'Linha com \"cordão de segurança\"', '<p>Implemento de seguran&ccedil;a exigido por alguns clientes.</p>\r\n<p><img src=\"../assets/files/cord&atilde;o_1.jpg\" alt=\"cord&atilde;o.jpg\"></p>', NULL, 157, 1, '2025-12-20 10:50:35', '2025-12-20 10:50:35', NULL),
