(266, 'Funil de alimentação', '<p>Funil de alimenta&ccedil;&atilde;o a ser instalado no local de envio de tampas.</p>', NULL, 164, 1, '2025-12-20 12:02:22', '2025-12-20 12:02:22', NULL),
