(284, 'Envolvimento do palete', NULL, '%', 182, 1, '2025-12-23 15:00:19', '2025-12-23 15:00:19', NULL),
(285, 'Configuração da pilha de paletes vazios', '<p>Os paletes vazios na entrada do equipamento podem ser manipulados de duas formas:</p>\r\n<p>1- Pilhas de paletes com os paletes dispostos ORDENADOS, ou seja, todos para o mesmo lado (todos de cabe&ccedil;a para cima por exemplo).</p>\r\n<p>2- Pilhas de paletes com os paletes dispostos de forma INTERCALADA (um palete de cabe&ccedil;a para cima e um de cabe&ccedil;a para baixo por exemplo).</p>', NULL, 183, 1, '2025-12-23 15:03:12', '2025-12-23 15:03:12', NULL),
(286, 'Número de estações de ENTRADA de paletes', NULL, NULL, 184, 1, '2025-12-23 15:04:34', '2025-12-23 15:04:34', NULL),
